const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const houston = ee.Geometry.Point([-95.3698, 29.7604]).buffer(20000); // 20km buffer for Houston
    const startDate = '2012-01-01';
    const endDate = '2014-12-31';

    // 2. Data Acquisition
    const viirsCollection = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
        .filterBounds(houston)
        .filterDate(startDate, endDate)
        .select('avg_rad');

    // Check if the base collection is empty
    const collectionSize = viirsCollection.size().getInfo();
    if (collectionSize === 0) {
        console.log("No VIIRS DNB data found for the 2012-2014 period in this location.");
        console.log("C1");
        return;
    }

    // 3. Processing: Separate collections for December and other months
    const decemberCollection = viirsCollection.filter(ee.Filter.calendarRange(12, 12, 'month'))
                                               .filter(ee.Filter.inList('year', [2012, 2013]));
    const otherMonthsCollection = viirsCollection.filter(ee.Filter.or(
        ee.Filter.calendarRange(1, 11, 'month'),
        ee.Filter.and(
            ee.Filter.calendarRange(12, 12, 'month'),
            ee.Filter.eq('year', 2014)
        )
    ));

    const decSize = decemberCollection.size().getInfo();
    const otherSize = otherMonthsCollection.size().getInfo();

    if (decSize === 0 || otherSize === 0) {
        console.log(`December collection size: ${decSize}`);
        console.log(`Other months collection size: ${otherSize}`);
        console.log("C1");
        return;
    }

    // 4. Calculation
    const decMeanImage = decemberCollection.mean();
    const otherMeanImage = otherMonthsCollection.mean();

    const scale = 1000;

    const decStats = decMeanImage.reduceRegion({
        reducer: ee.Reducer.mean().combine({ reducer2: ee.Reducer.count(), sharedInputs: true }),
        geometry: houston,
        scale: scale,
        maxPixels: 1e9
    }).getInfo();

    const otherStats = otherMeanImage.reduceRegion({
        reducer: ee.Reducer.mean().combine({ reducer2: ee.Reducer.count(), sharedInputs: true }),
        geometry: houston,
        scale: scale,
        maxPixels: 1e9
    }).getInfo();

    const decMean = decStats['avg_rad_mean'];
    const decCount = decStats['avg_rad_count'];
    const otherMean = otherStats['avg_rad_mean'];
    const otherCount = otherStats['avg_rad_count'];

    // 5. Validation & Final Answer
    if (decCount === 0 || otherCount === 0) {
        console.log(`Valid pixels (December): ${decCount}`);
        console.log(`Valid pixels (Other Months): ${otherCount}`);
        console.log("C2");
        return;
    }

    if (decMean === null || otherMean === null) {
        console.log(`December Mean Radiance: ${decMean}`);
        console.log(`Other Months Mean Radiance: ${otherMean}`);
        console.log("C3");
        return;
    }

    console.log(`December 2012/13 Images: ${decSize}`);
    console.log(`Other Months (2012-14) Images: ${otherSize}`);
    console.log(`Avg Radiance (Dec 2012/13): ${decMean.toFixed(2)}`);
    console.log(`Avg Radiance (Other Months): ${otherMean.toFixed(2)}`);

    if (decMean > otherMean) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log("D");
});
